
from pydantic import BaseModel, Field


class LoginRequest(BaseModel):
    # Credentials submitted by the user.
    username: str = Field(min_length=1)
    password: str = Field(min_length=1)


class UnlockRequest(BaseModel):
    # Lock identifier and credential.
    lock_id: str = Field(min_length=1)
    lock_password: str = Field(min_length=1)

    # Timestamp generated by the Smart Lock.
    timestamp: int

    # Unique value used to prevent replay attacks.
    nonce: str = Field(min_length=16)
